-- ============================================
-- Migracao: seed das perguntas e opcoes
-- ARQUIVO GERADO - nao edite a mao.
--   fonte:  data/questions.tsx (linha do cliente, versao_supabase)
--   gerado: do bundle transformado com esbuild, nunca transcrito a mao
-- 35 perguntas, 140 opcoes; toda pergunta tem exatamente uma correta.
-- Idempotente (replay-safe) via ON CONFLICT DO UPDATE.
-- ============================================

ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title, scenario = EXCLUDED.scenario, position = EXCLUDED.position;

ON CONFLICT (question_id, option_index) DO UPDATE SET
  option_text = EXCLUDED.option_text, is_correct = EXCLUDED.is_correct;
